export const CreateTradeRequest: MessageFns<CreateTradeRequest> = {
  fromJSON(object: any): CreateTradeRequest {
    return {
      bizType: isSet(object.bizType)
        ? globalThis.String(object.bizType)
        : isSet(object.biz_type)
        ? globalThis.String(object.biz_type)
        : "",
      bizTradeNo: isSet(object.bizTradeNo)
        ? globalThis.String(object.bizTradeNo)
        : isSet(object.biz_trade_no)
        ? globalThis.String(object.biz_trade_no)
        : "",
      userId: isSet(object.userId) ? BigInt(object.userId) : isSet(object.user_id) ? BigInt(object.user_id) : 0n,
      goodsType: isSet(object.goodsType)
        ? goodsTypeFromJSON(object.goodsType)
        : isSet(object.goods_type)
        ? goodsTypeFromJSON(object.goods_type)
        : GoodsType.GOODS_TYPE_UNSPECIFIED,
      payAmount: isSet(object.payAmount)
        ? BigInt(object.payAmount)
        : isSet(object.pay_amount)
        ? BigInt(object.pay_amount)
        : 0n,
      items: globalThis.Array.isArray(object?.items)
        ? object.items.map((e: any) => TradeItem.fromJSON(e))
        : [],
      originalAmount: isSet(object.originalAmount)
        ? BigInt(object.originalAmount)
        : isSet(object.original_amount)
        ? BigInt(object.original_amount)
        : 0n,
      discountAmount: isSet(object.discountAmount)
        ? BigInt(object.discountAmount)
        : isSet(object.discount_amount)
        ? BigInt(object.discount_amount)
        : 0n,
      baseReq: isSet(object.baseReq)
        ? BaseReq.fromJSON(object.baseReq)
        : isSet(object.base_req)
        ? BaseReq.fromJSON(object.base_req)
        : undefined,
    };
  },

  toJSON(message: CreateTradeRequest): unknown {
    const obj: any = {};
    if (message.bizType !== "") {
      obj.bizType = message.bizType;
    }
    if (message.bizTradeNo !== "") {
      obj.bizTradeNo = message.bizTradeNo;
    }
    if (message.userId !== 0n) {
      obj.userId = message.userId.toString();
    }
    if (message.goodsType !== GoodsType.GOODS_TYPE_UNSPECIFIED) {
      obj.goodsType = goodsTypeToJSON(message.goodsType);
    }
    if (message.payAmount !== 0n) {
      obj.payAmount = message.payAmount.toString();
    }
    if (message.items?.length) {
      obj.items = message.items.map((e) => TradeItem.toJSON(e));
    }
    if (message.originalAmount !== 0n) {
      obj.originalAmount = message.originalAmount.toString();
    }
    if (message.discountAmount !== 0n) {
      obj.discountAmount = message.discountAmount.toString();
    }
    if (message.baseReq !== undefined) {
      obj.baseReq = BaseReq.toJSON(message.baseReq);
    }
    return obj;
  },

  create<I extends Exact<DeepPartial<CreateTradeRequest>, I>>(base?: I): CreateTradeRequest {
    return CreateTradeRequest.fromPartial(base ?? ({} as any));
  },
  fromPartial<I extends Exact<DeepPartial<CreateTradeRequest>, I>>(object: I): CreateTradeRequest {
    const message = createBaseCreateTradeRequest();
    message.bizType = object.bizType ?? "";
    message.bizTradeNo = object.bizTradeNo ?? "";
    message.userId = object.userId ?? 0n;
    message.goodsType = object.goodsType ?? GoodsType.GOODS_TYPE_UNSPECIFIED;
    message.payAmount = object.payAmount ?? 0n;
    message.items = object.items?.map((e) => TradeItem.fromPartial(e)) || [];
    message.originalAmount = object.originalAmount ?? 0n;
    message.discountAmount = object.discountAmount ?? 0n;
    message.baseReq = (object.baseReq !== undefined && object.baseReq !== null)
      ? BaseReq.fromPartial(object.baseReq)
      : undefined;
    return message;
  },
};

